def remove_tuple(test_tup):
    """Write a function to remove the duplicates from the given tuple.

    Returns a tuple containing each distinct element once, sorted
    (e.g. ``(1, 3, 5, 2, 3, 5, 1, 1, 3)`` becomes ``(1, 2, 3, 5)``).
    If the elements are not mutually comparable, they are returned in
    order of first occurrence instead.
    """
    unique = []
    for item in test_tup:
        if item not in unique:
            unique.append(item)
    try:
        return tuple(sorted(unique))
    except TypeError:
        return tuple(unique)
